23	interface EditInput {
24	  old_string?: string;
25	  new_string?: string;
26	}
27	
28	interface ToolInput extends EditInput {
29	  file_path?: string;
30	  content?: string;
31	  edits?: EditInput[];
32	}
33	
34	interface HookInput {
35	  tool_name?: string;
36	  tool_input?: ToolInput;
37	}
38	// biome-ignore-end lint/style/useNamingConvention: Claude Code chooses these snake_case names.
