40	// Playwright's own values for each tolerance setting.
41	// Adding a setting that was missing is compared against these, so adding `retries: 2` counts
42	// as raising retries from 0 to 2.
43	const DEFAULT_TOLERANCES: Record<string, number> = {
44	  maxDiffPixels: 0,
45	  maxDiffPixelRatio: 0,
46	  threshold: 0.2,
47	  retries: 0,
48	};
