60	// ---- Reading a Claude Code hook payload ----
61	
62	// A Write replaces a whole file, so the text before is whatever is on disk now.
63	function changeFromWrite(file: string, input: ToolInput): Change {
64	  let before = "";
65	  if (existsSync(file)) {
66	    before = readFileSync(file, "utf8");
67	  }
68	  return { file, before, after: input.content ?? "" };
69	}
