71	// An Edit only shows the replaced snippet, so the guard compares the old and new snippets.
72	// MultiEdit sends a list of such snippets; a plain Edit is a list of one.
73	function changesFromEdit(file: string, input: ToolInput): Change[] {
74	  const edits = input.edits ?? [input];
75	  return edits.map((edit) => ({
76	    file,
77	    before: edit.old_string ?? "",
78	    after: edit.new_string ?? "",
79	  }));
80	}
