91	// ---- Reading a unified diff ----
92	
93	// A header line looks like `+++ b/tests/basket.spec.ts`, possibly followed by a tab and a date.
94	function pathFromHeader(header: string): string {
95	  const withoutMarker = header.slice(4);
96	  const withoutDate = withoutMarker.split("\t")[0];
97	  return withoutDate.replace(/^[ab]\//, "");
98	}
