100	// When a file is deleted the new path is /dev/null, so the old path names the file instead.
101	function fileFromHeaders(oldHeader: string, newHeader: string): string {
102	  if (newHeader.endsWith("/dev/null")) {
103	    return pathFromHeader(oldHeader);
104	  }
105	  return pathFromHeader(newHeader);
106	}
107	
108	// Lines that describe the diff rather than the code, and so belong to neither side.
109	function isDiffMetadata(line: string): boolean {
110	  return line.startsWith("diff ") || line.startsWith("@@") || line.startsWith("\\");
111	}
112	
113	// Context lines (a leading space, or an empty line) exist on both sides of the change.
114	function addHunkLine(change: Change, line: string): void {
115	  const marker = line[0];
116	  const text = line.slice(1);
117	  if (marker === " " || marker === undefined) {
118	    change.before += `${text}\n`;
119	    change.after += `${text}\n`;
120	  } else if (marker === "-") {
121	    change.before += `${text}\n`;
122	  } else if (marker === "+") {
123	    change.after += `${text}\n`;
124	  }
125	}
126	
127	// A new file starts with a `--- a/x` line directly followed by a `+++ b/x` line.
128	// Checking both lines stops a removed line that happens to begin with `--` from looking like one.
129	function isFileHeader(line: string, previous: string, next: string): boolean {
130	  if (line.startsWith("--- ") && next.startsWith("+++ ")) {
131	    return true;
132	  }
133	  return line.startsWith("+++ ") && previous.startsWith("--- ");
134	}
135	
136	// The second header line has both paths in view, so that is where a new file begins.
137	function startFileAtHeader(changes: Change[], line: string, previous: string): void {
138	  if (line.startsWith("+++ ")) {
139	    changes.push({ file: fileFromHeaders(previous, line), before: "", after: "" });
140	  }
141	}
142	
143	function changesFromDiff(diff: string): Change[] {
144	  const changes: Change[] = [];
145	  const lines = diff.split("\n");
146	  for (let index = 0; index < lines.length; index++) {
147	    const line = lines[index];
148	    const previous = lines[index - 1] ?? "";
149	    const next = lines[index + 1] ?? "";
150	    if (isFileHeader(line, previous, next)) {
151	      startFileAtHeader(changes, line, previous);
152	      continue;
153	    }
154	    const current = changes.at(-1);
155	    if (current !== undefined && !isDiffMetadata(line)) {
156	      addHunkLine(current, line);
157	    }
158	  }
159	  return changes;
160	}
161	
162	// ---- Reading standard input ----
163	
164	// Hook payloads are JSON objects; anything that does not parse as one is treated as a diff.
165	function parseHook(input: string): HookInput | undefined {
166	  try {
167	    const parsed: unknown = JSON.parse(input);
168	    if (typeof parsed === "object" && parsed !== null) {
169	      return parsed as HookInput;
170	    }
171	  } catch {
172	    // Not JSON, so it must be a diff.
173	  }
174	  return undefined;
175	}
176	
177	function readChanges(input: string): Change[] {
178	  const hook = parseHook(input);
179	  if (hook !== undefined) {
180	    return changesFromHook(hook);
181	  }
182	  return changesFromDiff(input);
183	}
184	
185	// ---- What a test promises ----
186	
187	function countMatches(text: string, pattern: RegExp): number {
188	  const matches = text.match(pattern);
189	  if (matches === null) {
190	    return 0;
191	  }
192	  return matches.length;
193	}
194	
195	// Counts expect(...), expect.soft(...) and expect.poll(...).
196	function countExpects(text: string): number {
197	  return countMatches(text, /\bexpect(\.\w+)*\s*\(/g);
198	}
199	
200	// Counts test.skip, test.fixme and the same on test.describe.
201	function countSkips(text: string): number {
202	  return countMatches(text, /\btest(\.describe)?\.(skip|fixme)\b/g);
203	}
204	
205	// Finds the closing quote of a string, given the position of its opening quote.
206	// A backslash escapes the next character, so "say \"hi\"" is read as one string.
207	function findStringEnd(text: string, openingQuote: number): number {
208	  const quote = text[openingQuote];
209	  for (let index = openingQuote + 1; index < text.length; index++) {
210	    if (text[index] === "\\") {
211	      index++;
212	    } else if (text[index] === quote) {
213	      return index;
214	    }
215	  }
216	  return text.length;
217	}
218	
219	// Finds where a call's arguments end, given the position just after its opening bracket.
220	// It skips over strings so that a bracket inside "($2.99)" does not end the call early.
221	// When the text ends before the call closes, as in a cut-off diff hunk, it returns the text end.
222	function findArgumentsEnd(text: string, start: number): number {
223	  let depth = 1;
224	  for (let index = start; index < text.length; index++) {
225	    const character = text[index];
226	    if (QUOTES.includes(character)) {
227	      index = findStringEnd(text, index);
228	    } else if (character === "(") {
229	      depth++;
230	    } else if (character === ")") {
231	      depth--;
232	      if (depth === 0) {
233	        return index;
234	      }
235	    }
236	  }
237	  return text.length;
238	}
239	
240	// Whitespace and a trailing comma are formatting, not meaning, so they must not count as a change.
241	function normalizeArguments(argumentsText: string): string {
242	  const singleSpaced = argumentsText.replace(/\s+/g, " ");
243	  const withoutTrailingComma = singleSpaced.replace(/,?\s*$/, "");
244	  return withoutTrailingComma.trim();
245	}
246	
247	// Lists every matcher call with its arguments, such as `.not.toHaveText("$12.40")`.
248	// The locator lives inside expect(...), not in the matcher, so changing a locator leaves these
249	// alone, while changing an expected value or dropping `.not` changes them.
250	function listMatchers(text: string): string[] {
251	  const matchers: string[] = [];
252	  for (const match of text.matchAll(/(\.not)?\.(to[A-Z]\w*)\s*\(/g)) {
253	    const negation = match[1] ?? "";
254	    const name = match[2];
255	    const start = (match.index ?? 0) + match[0].length;
256	    const end = findArgumentsEnd(text, start);
257	    const argumentsText = normalizeArguments(text.slice(start, end));
258	    matchers.push(`${negation}.${name}(${argumentsText})`);
259	  }
260	  return matchers;
261	}
262	
263	// Finds the largest number given to a setting, so `retries: process.env.CI ? 3 : 0` counts as 3.
264	function readTolerance(text: string, setting: string): number {
265	  const pattern = new RegExp(`\\b${setting}\\s*:\\s*([^,}\\n]+)`, "g");
266	  const values: number[] = [];
267	  for (const match of text.matchAll(pattern)) {
268	    const numbers = match[1].match(/\d*\.?\d+/g) ?? [];
269	    for (const number of numbers) {
270	      values.push(Number(number));
271	    }
272	  }
273	  if (values.length === 0) {
274	    return DEFAULT_TOLERANCES[setting];
275	  }
276	  return Math.max(...values);
277	}
278	
279	// ---- The verdict ----
280	
281	function findRaisedTolerance(change: Change): string | undefined {
282	  for (const setting of Object.keys(DEFAULT_TOLERANCES)) {
283	    const was = readTolerance(change.before, setting);
284	    const now = readTolerance(change.after, setting);
285	    if (now > was) {
286	      return `raises ${setting} (${was} -> ${now})`;
287	    }
288	  }
289	  return undefined;
290	}
291	
292	// Every matcher from before must still be there afterwards, each one matched only once,
293	// so that moving a matcher is fine but changing one is not.
294	function findChangedMatcher(change: Change): string | undefined {
295	  const remaining = listMatchers(change.after);
296	  for (const matcher of listMatchers(change.before)) {
297	    const position = remaining.indexOf(matcher);
298	    if (position === -1) {
299	      return `changes an expected value: ${matcher}`;
300	    }
301	    remaining.splice(position, 1);
302	  }
303	  return undefined;
304	}
305	
306	// Returns why the change weakens a test, or undefined when it does not.
307	function findWeakening(change: Change): string | undefined {
308	  const expectsBefore = countExpects(change.before);
309	  const expectsAfter = countExpects(change.after);
310	  if (expectsAfter < expectsBefore) {
311	    return `removes an expect (${expectsBefore} -> ${expectsAfter})`;
312	  }
313	  if (countSkips(change.after) > countSkips(change.before)) {
314	    return "adds test.skip or test.fixme";
315	  }
316	  return findRaisedTolerance(change) ?? findChangedMatcher(change);
317	}
318	
319	async function main(): Promise<void> {
320	  const input = await Bun.stdin.text();
321	  for (const change of readChanges(input)) {
322	    if (!isJudged(change.file)) {
323	      continue;
324	    }
325	    const reason = findWeakening(change);
326	    if (reason !== undefined) {
327	      console.error(`guard: ${change.file}: ${reason}`);
328	      process.exit(2);
329	    }
330	  }
331	  process.exit(0);
332	}
333	
334	await main();
