2	// seed: tests/seed.spec.ts
3	import { expect, test } from "@playwright/test";
4	
5	test.beforeEach(async ({ page, request }) => {
6	  await request.post("/__test/reset");
7	  await page.goto("/signin");
8	  await page.getByLabel("Email").fill("ana@pantryrun.test");
9	  await page.getByLabel("Password").fill("pantry");
10	  await page.getByRole("button", { name: "Sign in" }).click();
11	  await expect(page.getByText("Signed in as Ana Torres")).toBeVisible();
12	});
13	
14	test.describe("Seeing slots", () => {
15	  test("Shows one-hour slots from 08:00 to 20:00 for three dates", async ({ page }) => {
16	    // 1. Open Delivery slots.
17	    await page.goto("/slots");
18	    await expect(page.getByRole("group")).toHaveCount(3);
19	    await expect(page.getByRole("radio")).toHaveCount(36);
20	    await expect(page.getByRole("radio", { name: /Mar 11 08:00 to 09:00/ })).toBeVisible();
21	    await expect(page.getByRole("radio", { name: /Mar 13 19:00 to 20:00/ })).toBeVisible();
22	  });
23	
24	  test("Peak slots cost $4.99 and others $2.99", async ({ page }) => {
25	    await page.goto("/slots");
26	    await expect(page.getByRole("radio", { name: /Mar 12 17:00 to 18:00, \$4\.99/ })).toBeVisible();
27	    await expect(page.getByRole("radio", { name: /Mar 12 16:00 to 17:00, \$2\.99/ })).toBeVisible();
28	    await expect(page.getByRole("radio", { name: /Mar 12 19:00 to 20:00, \$2\.99/ })).toBeVisible();
29	  });
30	
31	  test("A slot with three or fewer places shows how many are left", async ({ page }) => {
32	    await page.goto("/slots");
33	    await expect(
34	      page.getByRole("radio", { name: /Mar 11 17:00 to 18:00, \$4\.99, 1 left/ }),
35	    ).toBeEnabled();
36	    await expect(
37	      page.getByRole("radio", { name: /Mar 11 10:00 to 11:00, \$2\.99, 3 left/ }),
38	    ).toBeEnabled();
39	  });
40	});
41	
42	test.describe("Booking rules", () => {
43	  test("A full slot shows Full and cannot be booked", async ({ page }) => {
44	    await page.goto("/slots");
45	    await expect(
46	      page.getByRole("radio", { name: /Mar 11 18:00 to 19:00, \$4\.99, Full/ }),
47	    ).toBeDisabled();
48	  });
49	
50	  test("Next-date slots close at 22:00 store time", async ({ page, request }) => {
51	    // 1. Set the store clock to 21:59 the evening before.
52	    await request.post("/__test/clock", { data: { at: "2026-03-10T21:59:00-05:00" } });
53	    await page.goto("/slots");
54	    await expect(page.getByRole("radio", { name: /Mar 11 08:00/ })).toBeEnabled();
55	    // 2. Set the store clock to 22:00.
56	    await request.post("/__test/clock", { data: { at: "2026-03-10T22:00:00-05:00" } });
57	    await page.goto("/slots");
58	    await expect(
59	      page.getByRole("radio", { name: /Mar 11 08:00 to 09:00, \$2\.99, Closed/ }),
60	    ).toBeDisabled();
61	    await expect(page.getByRole("radio", { name: /Mar 12 08:00/ })).toBeEnabled();
62	  });
63	
64	  test("The basket shows the booked slot and its fee", async ({ page }) => {
65	    await page.goto("/slots");
66	    await page.getByRole("radio", { name: /Mar 12 09:00 to 10:00/ }).check();
67	    await page.getByRole("button", { name: "Book slot" }).click();
68	    await expect(page).toHaveURL(/\/basket/);
69	    await expect(page.getByTestId("held-slots")).toHaveText("Thu, Mar 12, 09:00 to 10:00 ($2.99)");
70	  });
71	
72	  test("Checkout needs a booked slot", async ({ page }) => {
73	    await page.goto("/");
74	    await page
75	      .getByRole("article", { name: "Ground coffee 227 g" })
76	      .getByRole("button", { name: "Add" })
77	      .click();
78	    await page.goto("/basket");
79	    await page.getByLabel("Quantity of Ground coffee 227 g").fill("6");
80	    await page.getByRole("button", { name: "Update Ground coffee 227 g" }).click();
81	    await expect(page.getByRole("button", { name: "Checkout" })).toBeDisabled();
82	    await expect(page.getByTestId("checkout-blocked")).toHaveText(
83	      "Book a delivery slot to check out.",
84	    );
85	  });
86	});
