1	// spec: specs/substitutions.md
2	// seed: tests/seed.spec.ts
3	import { expect, type Page, test } from "@playwright/test";
4	
5	test.beforeEach(async ({ page, request }) => {
6	  await request.post("/__test/reset");
7	  await page.goto("/signin");
8	  await page.getByLabel("Email").fill("ana@pantryrun.test");
9	  await page.getByLabel("Password").fill("pantry");
10	  await page.getByRole("button", { name: "Sign in" }).click();
11	  await expect(page.getByText("Signed in as Ana Torres")).toBeVisible();
12	});
13	
14	async function addItem(page: Page, name: string) {
15	  await page.goto("/");
16	  await page
17	    .getByRole("article", { name, exact: true })
18	    .getByRole("button", { name: "Add" })
19	    .click();
20	  await expect(page.getByRole("status")).toHaveText(`Added ${name} to your basket`);
21	}
22	
23	async function switchOffSubstitutes(page: Page, name: string) {
24	  await page.goto("/basket");
25	  // The switch posts its form, and the shop redirects back to a freshly drawn basket.
26	  const reloaded = page.waitForResponse((response) => {
27	    const isPageLoad = response.request().method() === "GET";
28	    return isPageLoad && response.url().endsWith("/basket");
29	  });
30	  await page.getByLabel(`Allow substitutes for ${name}`).uncheck();
31	  await reloaded;
32	  await page.waitForLoadState();
33	  await expect(page.getByLabel(`Allow substitutes for ${name}`)).not.toBeChecked();
34	}
35	
36	// Six Ground coffee 227 g ($26.94) clears the $25.00 minimum. Book Mar 12 09:00 and check out.
37	async function checkOut(page: Page) {
38	  await addItem(page, "Ground coffee 227 g");
39	  await page.goto("/basket");
40	  await page.getByLabel("Quantity of Ground coffee 227 g").fill("6");
41	  await page.getByRole("button", { name: "Update Ground coffee 227 g" }).click();
42	  await page.goto("/slots");
43	  await page.getByRole("radio", { name: /Mar 12 09:00 to 10:00/ }).check();
44	  await page.getByRole("button", { name: "Book slot" }).click();
45	  await expect(page).toHaveURL(/\/basket/);
46	  await page.getByRole("button", { name: "Checkout" }).click();
47	  await expect(page).toHaveURL(/\/orders\//);
